from app.services.pricing import compute_total


def test_compute_total_without_tax_key():
    cart = {"items": [{"price": 10.0, "qty": 2}]}
    assert compute_total(cart) == 20.0


def test_compute_total_with_tax_key():
    cart = {"items": [{"price": 10.0, "qty": 1}], "tax": 1.5}
    assert compute_total(cart) == 11.5
